using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
using Elevator.Core.Project;using Elevator.Core.Calculations;using Elevator.Solution.Desktop;using Elevator.Solution.Bridge;
using Elevator.Reporting.Sheet;
using Elevator.Reporting.DesignNotes;
using Elevator.Reporting.Docx;
using Elevator.Reporting.Figures;
public static class BasicUiTests
{
 // Source root (config/ and Templates/): the parent of the binary folder, or an ancestor for artifacts/bin.
 static string Root(string bin){var parent=Directory.GetParent(bin.TrimEnd(Path.DirectorySeparatorChar));for(var d=parent;d!=null;d=d.Parent)if(Directory.Exists(Path.Combine(d.FullName,"config"))&&Directory.Exists(Path.Combine(d.FullName,"Templates")))return d.FullName;return parent.FullName;}
 static MainWindow w;static string output;static int checks;static List<string> names=new List<string>();
 static object Get(string n){return typeof(MainWindow).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(w);}static void Set(string n,object v){typeof(MainWindow).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(w,v);}static object Call(string n,params object[] a){return typeof(MainWindow).GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(w,a);}
 static IEnumerable<DependencyObject> Tree(DependencyObject n){yield return n;for(int i=0;i<VisualTreeHelper.GetChildrenCount(n);i++)foreach(var c in Tree(VisualTreeHelper.GetChild(n,i)))yield return c;}
 static Dictionary<string,TextBox> Editors(){return (Dictionary<string,TextBox>)Get("editors");}static Dictionary<string,ComboBox> Choices(){return (Dictionary<string,ComboBox>)Get("calculationChoices");}static ProjectSession Session(){return (ProjectSession)Get("session");}static CalculationWorkspace Space(){return (CalculationWorkspace)Get("calculations");}
 // The test owns its window: a close request it did not make (title-bar X, Alt+F4, taskbar, WM_CLOSE from another process)
 // is refused, because smoke mode skips the unsaved-changes prompt and a closed window ends app.Run while the test is still
 // awaiting, so neither the result nor an error would be written. The window is not activated, so it takes no keyboard focus.
 static bool testClosing;
 // Lifecycle trace, appended as it happens, so an early exit still leaves a record.
 static void Trace(string m){File.AppendAllText(Path.Combine(output,"ui-trace.log"),DateTime.Now.ToString("HH:mm:ss.fff")+" "+m+"\n");}
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;names.Add(name);}static void Click(string name){w.UpdateLayout();if(name.StartsWith("Calculate ")){/* Calculate buttons were replaced by live calculation: run the debounced calculation now. */Call("RunLiveCalculation");return;}Tree(w).OfType<Button>().First(b=>Convert.ToString(b.Content)==name).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}static string Text(){return String.Join("\n",Tree((DependencyObject)Get("calculationResults")).OfType<TextBlock>().Select(t=>t.Text));}
 static async Task Shot(string name){w.UpdateLayout();await Task.Delay(150);Call("Screenshot",Path.Combine(output,name+".png"));}
 static async Task SelectMode(int index){w.UpdateLayout();await Task.Delay(150);Choices()["Mode"].SelectedIndex=index;w.UpdateLayout();await Task.Delay(150);}
 [STAThread]public static int Main(string[] args)
 {
  output=args[0];Directory.CreateDirectory(output);var app=new Application();app.DispatcherUnhandledException+=(cs,ce)=>Wire.Write(Path.Combine(output,"ui-crash.json"),new{Source="Dispatcher",Error=ce.Exception.ToString()});AppDomain.CurrentDomain.UnhandledException+=(cs,ce)=>Wire.Write(Path.Combine(output,"ui-crash.json"),new{Source="AppDomain",Error=Convert.ToString(ce.ExceptionObject)});Trace("start");w=new MainWindow(new string[0]);Set("smoke",true);int exit=1;app.Exit+=(cs,ce)=>Trace("app Exit "+ce.ApplicationExitCode);w.ShowActivated=false;w.Closing+=(cs,ce)=>{if(testClosing){Trace("window Closing (test)");return;}ce.Cancel=true;Trace("external close request refused "+Environment.StackTrace);};w.Closed+=(cs,ce)=>Trace("window Closed");
  w.Loaded+=async(s,e)=>{Trace("Loaded");try{
   Call("ShowPage","CALCULATIONS");Check(Session().Project.Calculations.Mode=="Basic"&&new[]{"CarMassKg","CounterweightMassKg","MachineMassKg","CarSideAdditionalSuspendedMassKg","CounterweightSideAdditionalSuspendedMassKg"}.All(f=>Editors().ContainsKey("Calculations."+f))&&!Editors().ContainsKey("Calculations.MachineCgOffsetXMm"),"New project uses compact Basic mass form, no Advanced fields");
   var bin=AppDomain.CurrentDomain.BaseDirectory;var p=ProjectJson.Deserialize(File.ReadAllText(Path.Combine(bin,"reviewed-example.elevator.json")));Set("session",new ProjectSession(p));Call("ResetCalculations");Call("ShowPage","CALCULATIONS");Check(Session().Project.Calculations.Mode=="Basic","Empty older project selects Basic, no fabricated masses");Check(Editors()["Calculations.CarMassKg"].Text=="","No example masses in new/empty project");
   p.Info.Name="SYNTHETIC BASIC UI TEST — NOT DESIGN INPUTS";p.Suspension.RopeCount=null;Call("ShowPage","CALCULATIONS");Editors()["Calculations.CarMassKg"].Text="500";Editors()["Calculations.CounterweightMassKg"].Text="800";Editors()["Calculations.MachineMassKg"].Text="300";Click("Calculate load distribution");Check(Space().Result.Reactions!=null&&Space().Result.Mode=="Basic"&&Space().Result.TotalMassKg==2050,"Calculate with three masses and existing capacity, no rope count / Advanced inputs");await Shot("01-basic-form-results");
   var scroll=(ScrollViewer)Get("pageScroll");scroll.ScrollToVerticalOffset(250);await Shot("02-derived-distances");scroll.ScrollToBottom();await Shot("02b-labelled-load-point");Check(Text().Contains("Derived distances")&&Tree(w).OfType<TextBlock>().Any(t=>t.Text.Contains("Machine load point")),"Derived distances and labelled native load point rendered");
   var g=Space().Geometry;Editors()["Calculations.MachineMassKg"].Text="350";Check(Space().Result==null&&!Text().Contains("20.111"),"Mass edit hides old results");Click("Calculate load distribution");Check(Object.ReferenceEquals(g,Space().Geometry)&&Space().Result.TotalMassKg==2100,"Mass-only edit reuses geometry");
   ((ListBox)Get("navigation")).SelectedIndex=1;Editors()["Shaft.WidthMm"].Text="1650";Editors()["Shaft.DepthMm"].Text="1800";((ListBox)Get("navigation")).SelectedIndex=7;Click("Calculate load distribution");Check(Space().Geometry.ShaftWidthMm==1650&&Space().Result.SimplifiedGeometry.LoadReference.X!=g.TractionCentre.X&&Space().Result.SimplifiedGeometry.LongitudinalSpanMm!=g.Bearings.Single(b=>b.Id=="P3").Centre.Y-g.Bearings.Single(b=>b.Id=="P4").Centre.Y,"Geometry edits update datum, lever arms and results automatically");scroll.ScrollToVerticalOffset(240);await Shot("03-resized-shaft");
   // Invalid Advanced editor text remains an error in Advanced, but is irrelevant in Basic.
   w.UpdateLayout();await Task.Delay(150);Choices()["Mode"].SelectedIndex=1;w.UpdateLayout();await Task.Delay(150);Wire.Write(Path.Combine(output,"mode-switch-diagnostic.json"),new{Mode=Session().Project.Calculations.Mode,Editors=Editors().Keys.ToArray(),Choices=Choices().Keys.ToArray()});Editors()["Calculations.MachineCgOffsetXMm"].Text="invalid";Choices()["Mode"].SelectedIndex=0;Check(Space().Result!=null&&Space().Result.Mode=="Basic"&&Space().IsCurrent(Session().Project,(DesignContext)Get("context")),"Mode change recalculates at once: the Basic result is current");Click("Calculate load distribution");Check(Space().Result.Reactions!=null,"Malformed unused Advanced editor does not block Basic");
   Session().FilePath=Path.Combine(output,"UI-Basic-saved.elevator.json");Click("Save");var opened=new ProjectSession(new ElevatorProject());opened.Open(Session().FilePath);Check(opened.Project.Calculations.Mode=="Basic"&&opened.Project.Calculations.MachineMassKg==350,"Basic mode and canonical shared masses save/reopen");Set("session",opened);Call("ResetCalculations");Call("ShowPage","CALCULATIONS");
   Editors()["Calculations.CarMassKg"].Text="";Click("Calculate load distribution");Check(Space().Result.Reactions==null&&Text().Contains("Empty car mass"),"Missing required mass unavailable");await Shot("04-missing");Editors()["Calculations.CarMassKg"].Text="500";
   var optional=Tree(w).OfType<Expander>().First(x=>Convert.ToString(x.Header).StartsWith("Optional additional"));optional.IsExpanded=true;w.UpdateLayout();await Task.Delay(150);
   // Click event alone does not toggle CheckBox in a programmatic test: use explicit IsChecked then Click.
   var box=Tree(w).OfType<CheckBox>().First(c=>Convert.ToString(c.Content)=="Include chassis assembly mass");box.IsChecked=true;box.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));w.UpdateLayout();await Task.Delay(150);Editors()["Calculations.ChassisMassKg"].Text="40";Click("Calculate load distribution");Check(Space().Result.TotalMassKg==2140&&!Editors().ContainsKey("Calculations.ChassisCgOffsetXMm"),"Included optional assembly mass needs no CG / counted once");
   w.Width=760;w.Height=640;scroll.ScrollToBottom();await Shot("05-narrow-preview");Check(scroll.ScrollableHeight>0,"Small window remains scrollable");w.Width=1220;w.Height=820;
   // Populated legacy Advanced project must open in Advanced and return identical results after round-trip mode switching.
   string root=Root(bin);var advanced=ProjectJson.Deserialize(File.ReadAllText(Path.Combine(root,"tests/fixtures/SYNTHETIC.elevator.json")));Set("session",new ProjectSession(advanced));Call("ResetCalculations");Call("ShowPage","CALCULATIONS");Check(Choices()["Mode"].SelectedValue.ToString()=="Advanced","Legacy populated Advanced project not converted");Click("Calculate P1–P4 & rope tensions");var before=Space().Result;await SelectMode(0);Click("Calculate load distribution");Check(Space().Result.Mode=="Basic","Basic has independent result/model identity");await SelectMode(1);Click("Calculate P1–P4 & rope tensions");Check(before.Reactions.All(b=>Math.Abs(Space().Result.Reactions.Single(a=>a.Id==b.Id).UpwardN-b.UpwardN)<1e-8),"Advanced inputs and results restored unchanged");await Shot("06-advanced-preserved");
   opened.Project.Info.Name="SYNTHETIC BASIC NATIVE ROUNDTRIP";opened.Project.Calculations.Mode="Basic";Set("session",opened);Call("ResetCalculations");Set("outputFolder",output);Set("outputName","Basic-AllFour.dwg");Call("ShowPage","DRAWINGS");await (Task)Call("Generate");var native=(GenerationResponse)Get("last");Check(native.Success&&native.ViewsGenerated.Length==4,"Basic mode canonical inputs survive native four-view generate/reopen");Wire.Write(Path.Combine(output,"native-generation.json"),native);
   exit=0;
  }catch(Exception ex){Wire.Write(Path.Combine(output,"ui-error.json"),new{Error=ex.ToString()});}finally{Wire.Write(Path.Combine(output,"basic-ui-tests.json"),new{Status=exit==0?"PASS":"FAIL",Assertions=checks,Checks=names,Method="Real WPF controls/rendering driven by programmatic events; native AutoCAD generation. Not mouse/keyboard testing."});testClosing=true;w.Close();}};app.Run(w);Trace("app.Run returned, exit "+exit);return exit;
 }
}
